export const title = "How to Choose Pegboard Accessories That Fit Your Board";
export const metaTitle = "How to Choose Pegboard Accessories That Fit";
export const metaDescription = "Identify the board system, then match hole shape, hole dimensions, spacing, panel thickness, rear clearance, and the accessory's retention design..";
